/**@description 弹窗需要实现的方法 */
declare interface AlertClass {
    /**@description 显示alert */
    show(option: AlertOption): void;

    /**@description 关闭alert */
    close(): Promise<void> | void;
}
/**@description 弹窗通用参数 */
declare interface AlertOption {
    /**@description 标题 */
    title?: string;
    /**@description 文本*/
    content: string;
    /**@description 是否显示取消按钮 */
    /**@description 用来标识弹出框，后面可指定tag进行关闭所有相同tag的弹出框 */
    tag?: number;
    showCancel?: boolean;
    /**@description 取消文本 默认为“取消” */
