declare interface UIClass<T extends UIView> {
    new(): T;
    /**
     *@description 视图prefab 地址 resources目录下如z_panels/WeiZoneLayer,
     * 如果是在主场景上的节点
     * static getPrefabUrl(){
     *   return `@LoginView`;
     * } 
     */
    getPrefabUrl?(): string;
}


/**@description UIManager open参数说明 */
declare interface OpenOption {
    /**@description 打开界面的类型 */
    type?: UIClass<UIView>;

    /**@description 视图绑定预置资源所在bundle,默认为resources目标 */
    bundle?: string;
    /**@description 节点层级，默认为0 */

    /**界面路径 */
    url?: string;

    /**层级 */
    zIndex?: number;
    /**
     * @description 
     * delay > 0 时间未加载界面完成显示加载动画，
     * delay = 0 则不显示加载动画，但仍然会显示UILoading,在加载界面时阻挡玩家的触摸事件
     * delay 其它情况以UILoading的默认显示时间为准
     */
    delay?: number;
    /**@description 默认""
     * 界面名字，如商城，个人信息,当delay>0时，加载超时后，会提示显示某某界面失败 
     * 否则默认提示加载界面失败
     **/
    name?: string;
    /**@description 是否是预加载预置资源，默认为false */
    preload?: boolean;
    /**@description 用户自定义参数 */
    args?: any | any[];
    /**@description 是否懒释放 */
    isLazyRelease?: boolean;

    /**是否展示系统loading */
    showLoading?: boolean;
    /**是否展示系统UILoading */
    showUILoading?: boolean;
}

/**@description 弹窗参数说明 */
type CacheMode = import("../framework/defines/Macros").Define.CacheMode;
declare interface PopupOpenOption extends OpenOption {

    /** 立刻展示（将会挂起当前展示中的弹窗） */
    immediately?: boolean;
    /** 立即展示时是否隐藏当前展示弹窗 */
    hideCurrent?: boolean;

    /**@description 弹出缓存模式 */
    mode?: CacheMode;

    /**@description 弹窗阶段事件 */
    onBeforeShow?: () => Promise<void>;     //弹窗展示前
    onAfterShow?: () => void;               //弹窗展示后（动画播放完毕）
    onBeforHide?: () => Promise<void>       //弹窗隐藏前
    onAfterHide?: () => void;               //弹窗隐藏后 
}

