     * String.format("{0}-->{1}-->{2}","one","two","three") | String.format("{0}-->{1}-->{2}",["one","two","three"])
     * => "one-->two-->three"
     * */
    format(...args: any[]): string;
}

/**@deprecated array扩展*/
interface Array<T> {
    /**
     * 清空数组
     */
    clear(): void

    /**
     * 拷贝数组
     * @returns {Array}
     */
    clone(): T[];

    /**
     * 随机获得数组中的一个元素
     * @returns {any}
     */
    getRandomOne(): T

    /**
     * 随机获取数组中N个元素
     * @returns {any[]}
     */
    getRandomCount(count: number): T[]

    /**
     * 随机获取数组中N个不同元素
     * @returns {any[]}
     */
    getRandomCountDiff(count: number): T[]


    /**
     * 获得除excpt以外的随机项
     * @param except 去除项，单项或者数组
     * @param number 返回数量
     * @returns {any} 返回数组或者项
     */
    getRandomExcept(except: T, number: number = 1): T[] | T;
    getRandomExcept(except: T[], number: number = 1): T[] | T;

    /**
     * 获得除exceptId数组下标以外的项
     * @param exceptId 去除的数组下标，单项或者数组 
     * @param number 返回数量
     *  @returns {any} 返回数组或者项
     */
    getRanomExceptIdx(exceptId: number, number: number = 1): T[] | T;
    getRanomExceptIdx(exceptId: number[], number: number = 1): T[] | T;


    /**合并其他数组 */
    addRange(...items: T[]): T[]


    /**
     * 插入item到idx位置
     * @param {number} idx
     * @param item
     */
    insert(idx: number, item: any): void;

    /**
     * 移除idx位置上的元素并返回
     * @param {number} idx
     * @returns {any}
     */
    removeAt(idx: number): T

    /**
     * 移除项
     * @param item
     */
    remove(...item: any[]): void;

    /**
     * 从index位开始移除count个元素
     * @param {number} idx
     * @param {number} count
     * @returns {any}
     */
    removeRange(idx: number, count: number): T

    /**
     * 按条件删除项，返回删除的项列表
     * @param {(value?: any, index?: number, array?: T[]) => boolean} match
     * @returns {Array}
     */
    removeByMatch(match: (value?: any, index?: number, array?: T[]) => boolean): Array

    /**
     * 返回数组是否存在元素
     * @param item
     * @returns {boolean}
     */
    contains(item: T): boolean

    /**
     * 去重
     * @returns {Array}
     */
    distinct(): Array

    /**
     * 求和
     * @returns {number}
     */
    sum(): number

    /**
     * 打乱自身
     * @returns {T[]}
     */
    upset(): T[]

    getMax(): T

    getMin(): T

    /**
     * 求几个数组的并集
     * @param {Array} arrs
     * @returns {Array}
     */
    getUnion(...arrs: T[]): T

    /**
     * 求几个数组的交集
     * @param {Array} arrs
     * @returns {Array}
     */
    getIntersect(...arrs: T[]): T

    /**
     * 生成随机字符串
     */
    generateUUID(): string;
}

interface ArrayConstructor {
    /**
     * 打乱数组
     * @param {Array} arr
     * @returns {Array}
     */
    shuffle<T>(arr: T): T;

    /**
     * 返回多个数组的并集
     * @param arrs 
     */
    getUnion<T>(...arrs: T): T;

    /**
     * 返回多个数组的交集
     * @param arrs 
     */
    getIntersect<T>(...arrs: T): T;
}


interface Math {
    /**
     * 返回区间内随机数
     * @param list 
     */
    getRandom(list: number[]): number
    getRandom(a: number, b: number): number

    /**
     * 返回区间内随机整数
